import React from 'react';

const Updates = () => {
    return (
        <div className="overflow-hidden bg-primary py-[7px] text-[0.8rem] text-white">
            <div className="mx-auto flex max-w-[1280px] items-center gap-0 px-6">
                <span className="mr-4 shrink-0 whitespace-nowrap rounded-[2px] bg-ternary px-3 py-[3px] text-[0.68rem] font-bold uppercase tracking-[0.1em] text-primary">
                    Updates
                </span>
                <div className="flex-1 overflow-hidden">
                    <p className="animate-scrolltxt whitespace-nowrap text-white/90">
                        🎓 NCICST-25 National Conference Registration Open — April 10-11, 2025 &nbsp;|&nbsp; 📋 B.Tech Admissions 2025-26 via KEAM Now Open &nbsp;|&nbsp; 🏆 CEC Team Wins Smart Kerala Hackathon 2025 &nbsp;|&nbsp; 📢 KTU S6/S8 Examination Schedule Published &nbsp;|&nbsp; ✅ 100% Placement — CSE &amp; ECE Batch 2024
                    </p>
                </div>
            </div>
        </div>
    );
};

export default Updates;
